SELECT breakdown_value AS `context.columns.breakdown_value`, tuple(uniq(filtered_person_id), NULL) AS `context.columns.visitors`, tuple(sum(filtered_pageview_count), NULL) AS `context.columns.views`, divide(`context.columns.visitors`.1, sum(`context.columns.visitors`.1) OVER ()) AS `context.columns.ui_fill_fraction` FROM (SELECT any(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id)) AS filtered_person_id, count() AS filtered_pageview_count, events__session.`$end_pathname` AS breakdown_value, events__session.session_id AS session_id, any(events__session.`$is_bounce`) AS is_bounce, min(events__session.`$start_timestamp`) AS start_timestamp FROM events_json AS events LEFT JOIN (SELECT path(nullIf(nullIf(argMaxMerge(raw_sessions.end_url), 'null'), '')) AS `$end_pathname`, toString(reinterpretAsUUID(bitOr(bitShiftLeft(raw_sessions.session_id_v7, 64), bitShiftRight(raw_sessions.session_id_v7, 64)))) AS session_id, if(equals(uniqMerge(raw_sessions.pageview_uniq), 0), NULL, not(or(greater(uniqMerge(raw_sessions.pageview_uniq), 1), greater(uniqMerge(raw_sessions.autocapture_uniq), 0), greaterOrEquals(dateDiff('second', min(toTimeZone(raw_sessions.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions.max_timestamp, 'UTC'))), 10)))) AS `$is_bounce`, min(toTimeZone(raw_sessions.min_timestamp, 'UTC')) AS `$start_timestamp`, raw_sessions.session_id_v7 AS session_id_v7 FROM raw_sessions WHERE and(equals(raw_sessions.team_id, TEAM_ID), greaterOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions.session_id_v7) AS events__session ON equals(toUInt128(toUUIDOrNull(events.properties.`$session_id`)), events__session.session_id_v7) LEFT OUTER JOIN (SELECT argMax(person_distinct_id_overrides.person_id, person_distinct_id_overrides.version) AS person_id, person_distinct_id_overrides.distinct_id AS distinct_id FROM person_distinct_id_overrides WHERE equals(person_distinct_id_overrides.team_id, TEAM_ID) GROUP BY person_distinct_id_overrides.distinct_id HAVING equals(argMax(person_distinct_id_overrides.is_deleted, person_distinct_id_overrides.version), 0) SETTINGS optimize_aggregation_in_order=1) AS events__override ON equals(events.distinct_id, events__override.distinct_id) WHERE and(equals(events.team_id, TEAM_ID), and(or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), or(equals(events.event, '$pageview'), equals(events.event, '$screen')), 1)) GROUP BY session_id, breakdown_value) GROUP BY `context.columns.breakdown_value` HAVING isNotNull(`context.columns.breakdown_value`) ORDER BY `context.columns.visitors` DESC, `context.columns.views` DESC, `context.columns.breakdown_value` ASC LIMIT 100
